mapper.select:
SELECT *
FROM reconciliation_snapshot
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND scenario_code=#{scenario}
AND cutoff_id=#{cutoffId}
AND scope_digest=#{digest} FOR UPDATE

SELECT *
FROM reconciliation_snapshot
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{id}

mapper.update:
UPDATE reconciliation_snapshot
SET state=#{state}, manifest_json=#{manifest}, completed_at=#{completedAt}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND id=#{id}
AND state='EXPORTING'

mapper.select:
SELECT part_no, row_count, sha256, payload
FROM snapshot_part
WHERE enterprise_id=#{enterpriseId}
AND warehouse_id=#{warehouseId}
AND snapshot_id=#{snapshotId}
AND part_no > #{afterPart}
ORDER BY part_no
LIMIT 2

SELECT b.id, b.owner_id, b.sku_id, b.lot_id, l.on_hand_after AS on_hand_qty, k.base_unit
FROM stock_balance b
LEFT JOIN sku k ON k.enterprise_id=b.enterprise_id AND k.id=b.sku_id
LEFT JOIN stock_ledger l ON l.enterprise_id=b.enterprise_id AND l.warehouse_id=b.warehouse_id
  AND l.balance_id=b.id AND l.balance_version=(
    SELECT MAX(h.balance_version) FROM stock_ledger h
    WHERE h.enterprise_id=b.enterprise_id AND h.warehouse_id=b.warehouse_id
      AND h.balance_id=b.id AND h.created_at < #{cutoff})
WHERE b.enterprise_id=#{enterpriseId} AND b.warehouse_id=#{warehouseId}
  AND b.created_at < #{cutoff}

  AND (l.id IS NOT NULL OR NOT EXISTS (
    SELECT 1 FROM stock_ledger first_entry WHERE first_entry.enterprise_id=b.enterprise_id AND first_entry.warehouse_id=b.warehouse_id
      AND first_entry.balance_id=b.id AND first_entry.balance_version=1 AND first_entry.created_at >= #{cutoff}
      AND first_entry.on_hand_after=first_entry.on_hand_delta))
AND b.id > #{afterId}
ORDER BY b.id LIMIT #{limit}

mapper.update:
UPDATE reconciliation_snapshot SET last_balance_id=#{afterId}, part_count=#{parts}, total_rows=#{rows},
  units_json=#{units}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId} AND warehouse_id=#{warehouseId} AND id=#{id}
  AND state='EXPORTING' AND version=#{version}
